function throws(callable $fn,string $contains):void{try{$fn();}catch(Throwable $e){if(!str_contains($e->getMessage(),$contains))throw new RuntimeException('Unexpected error: '.$e->getMessage());return;}throw new RuntimeException('Expected exception containing '.$contains);}
