 $zipPath=sys_get_temp_dir().'/mybb-test-'.bin2hex(random_bytes(5)).'.zip';$zip=new ZipArchive();$zip->open($zipPath,ZipArchive::CREATE);$zip->addFromString($source,$content);if($externalType)$zip->setExternalAttributesName($source,ZipArchive::OPSYS_UNIX,($externalType|0644)<<16);foreach($extras as $extra)$zip->addFromString($extra,'not declared');if($symlink){$zip->addFromString('upload/symlink.php','../../outside.php');$zip->setExternalAttributesName('upload/symlink.php',ZipArchive::OPSYS_UNIX,(0120777<<16));}if($directorySymlink){$zip->addEmptyDir('upload/linkdir');$zip->setExternalAttributesName('upload/linkdir/',ZipArchive::OPSYS_UNIX,(0120777<<16));}$zip->close();$kp=sodium_crypto_sign_keypair();$secret=sodium_crypto_sign_secretkey($kp);$public=sodium_crypto_sign_publickey($kp);
