 file_put_contents($root.'/global.php',$runtime);
 $file='inc/plugins/sample_lifecycle.php';$ledger=['sample-managed'=>['version'=>'1.0.0','active'=>false,'files'=>[$file=>['sha256'=>hash_file('sha256',$root.'/'.$file),'role'=>'plugin']]]];file_put_contents($root.'/inc/plugins/data/mybb-tooling/installed.json',json_encode($ledger,JSON_THROW_ON_ERROR));
 $entry=dirname(__DIR__).'/mybb-cli/bin/mybb';$run=static function(array $command):array{$pipes=[];$proc=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($proc))throw new RuntimeException('Could not start lifecycle command');fclose($pipes[0]);$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$status=proc_close($proc);if($status!==0)throw new RuntimeException('Lifecycle CLI failed: '.$stderr.$stdout);return [$status,$stdout,$stderr];};
 [$code,$stdout,$stderr]=$run([PHP_BINARY,$entry,'plugin','activate','sample-managed','--path='.$root,'--dry-run','--json']);eq($code,0);eq($stderr,'');eq(json_decode($stdout,true,512,JSON_THROW_ON_ERROR)['status'],'dry_run');eq(json_decode($stdout,true,512,JSON_THROW_ON_ERROR)['activation_cache_missing'],true);eq(is_file($root.'/cache/activation-state.json'),false);eq(is_file($root.'/cache/plugins.php'),false);
 [$code,$stdout,$stderr]=$run([PHP_BINARY,$entry,'plugin','activate','sample-managed','--path='.$root,'--yes','--json']);eq($code,0);eq($stderr,'');eq(json_decode($stdout,true,512,JSON_THROW_ON_ERROR)['status'],'activated');eq(file_get_contents($root.'/cache/lifecycle-callback.txt'),'activated');$saved=json_decode(file_get_contents($root.'/inc/plugins/data/mybb-tooling/installed.json'),true,512,JSON_THROW_ON_ERROR);eq($saved['sample-managed']['active'],true);
 [$code,$stdout,$stderr]=$run([PHP_BINARY,$entry,'plugin','deactivate','sample-managed','--path='.$root,'--yes','--json']);eq($code,0);eq($stderr,'');eq(json_decode($stdout,true,512,JSON_THROW_ON_ERROR)['status'],'deactivated');eq(file_get_contents($root.'/cache/lifecycle-callback.txt'),'deactivated');$saved=json_decode(file_get_contents($root.'/inc/plugins/data/mybb-tooling/installed.json'),true,512,JSON_THROW_ON_ERROR);eq($saved['sample-managed']['active'],false);
