test('catalog client preserves shared error codes and classifies transient, authorization, revoked, and size failures',function(){$notFound=CatalogClient::classifyHttpFailure(404);eq($notFound->errorCode,'not_found');eq($notFound->retryable,false);$authorization=CatalogClient::classifyHttpFailure(403);eq($authorization->errorCode,'authorization_failed');$revoked=CatalogClient::classifyHttpFailure(410,['code'=>'release_revoked','message'=>"Release revoked\n\033[31m",'retryable'=>false,'request_id'=>'catalog-req-123']);eq($revoked->errorCode,'release_revoked');eq($revoked->retryable,false);eq($revoked->requestId,'catalog-req-123');if(preg_match('/[\x00-\x1f\x7f-\x9f]/',$revoked->getMessage()))throw new RuntimeException('Catalog error message contains terminal control characters');$limited=CatalogClient::classifyHttpFailure(429);eq($limited->errorCode,'rate_limited');eq($limited->retryable,true);$server=CatalogClient::classifyHttpFailure(503);eq($server->retryable,true);$timeout=CatalogClient::classifyTransportFailure(CURLE_OPERATION_TIMEDOUT,'connection timed out');eq($timeout->errorCode,'catalog_unavailable');eq($timeout->retryable,true);$tls=CatalogClient::classifyTransportFailure(CURLE_SSL_CACERT,'certificate verify failed');eq($tls->errorCode,'catalog_tls_error');eq($tls->retryable,false);$large=CatalogClient::classifyTransportFailure(CURLE_ABORTED_BY_CALLBACK,'callback aborted',true);eq($large->errorCode,'response_too_large');eq($large->retryable,false);});
