lated)),3);$targetLink=$tmp.'/installer-target-link';symlink($realParent,$targetLink);[$code,$stdout,$stderr]=$run([PHP_BINARY,$entry,'check',$targetLink,'--json']);eq($code,1);$error=json_decode($stdout,true,512,JSON_THROW_ON_ERROR);eq($error['error']['code'],'install_failed');});
test('fixture generator creates and safely resets the named synthetic scenarios',function(){ $name='suite-'.bin2hex(random_bytes(4));$runtime=dirname(__DIR__).'/sample-sites/runtime';$root=$runtime.'/'.$name;$sidecar=$runtime.'/'.$name.'.FIXTURE.json';$outside=$runtime.'/_outside/'.$name;$script=dirname(__DIR__).'/sample-sites/create-fixture.php';$run=static function(array $command):void{$pipes=[];$proc=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($proc))throw new RuntimeException('Could not start fixture generator');fclose($pipes[0]);$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$status=proc_close($proc);if($status!==0)throw new RuntimeException('Fixture generation failed: '.$stdout.$stderr);};$remove=static function(string $path)use(&$remove):void{if(is_link($path)||is_file($path)){@unlink($path);return;}if(!is_dir($path))return;foreach(new FilesystemIterator($path,FilesystemIterator::SKIP_DOTS) as $entry)$remove($entry->getPathname());@rmdir($path);};try{$run([PHP_BINARY,$script,$name,'--scenario=modified-owned']);$fixture=json_decode(file_get_contents($sidecar),true,512,JSON_THROW_ON_ERROR);eq($fixture['scenario'],'modified-owned');$ledger=json_decode(file_get_contents($root.'/inc/plugins/data/mybb-tooling/installed.json'),true,512,JSON_THROW_ON_ERROR);eq(isset($ledger['sample-owned']),true);$run([PHP_BINARY,$script,$name,'--scenario=symlink-parent','--reset']);eq(is_link($root.'/inc/plugins/escape'),true);eq(file_get_contents($outside.'/sentinel.txt'),'Must remain untouched.');$run([PHP_BINARY,$script,$name,'--scenario=empty','--reset']);eq(count(scandir($root)),2);eq(json_decode(file_get_contents($sidecar),true,512,JSON_THROW_ON_ERROR)['scenario'],'empty');$run([PHP_BINARY,$script,$name,'--scenario=partial','--reset']);eq(is_file($root.'/inc/config.default.php'),true);eq(is_file($root.'/inc/config.php'),false);$run([PHP_BINARY,$script,$name,'--scenario=unrelated','--reset']);eq(is_file($root.'/uploads-user-content.txt'),true);$run([PHP_BINARY,$script,$name,'--scenario=interrupted','--reset']);eq(is_file($root.'/inc/plugins/data/mybb-tooling/transactions/simulated-interrupted-install/journal.json'),true);}finally{$remove($root);@unlink($sidecar);$remove($outside);}});
