test('installer write plans include exact core and signed package destinations with core-only isolation',function(){
 $core=[['path'=>'index.php','bytes'=>120],['path'=>'inc/class_core.php','bytes'=>2048]];
 $packages=['mybb-toolchain'=>['files'=>[['destination'=>'inc/plugins/mybb-tooling/autoload.php']]],'mybbresources-repository'=>['files'=>[['destination'=>'inc/plugins/mybbresources_repository.php']]]];
 $sections=MyBB\Installer\InstallPlanOutput::freshInstallSections($core,['empty-directory'],$packages,true,'/tmp/site.mybb-install-transaction.json');
 $rendered=MyBB\Installer\InstallPlanOutput::render('VERIFIED WRITE PLAN',$sections);
 foreach(['index.php (120 bytes)','inc/class_core.php (2048 bytes)','mybb-toolchain: inc/plugins/mybb-tooling/autoload.php','mybbresources-repository: inc/plugins/mybbresources_repository.php','inc/plugins/data/mybb-tooling/installed.json (package ownership ledger)','/tmp/site.mybb-install-transaction.json','inc/plugins/data/mybb-tooling/transactions'] as $expected)if(!str_contains($rendered,$expected))throw new RuntimeException('Verified write plan omitted '.$expected);
 $coreOnly=MyBB\Installer\InstallPlanOutput::render('VERIFIED WRITE PLAN',MyBB\Installer\InstallPlanOutput::freshInstallSections($core,['empty-directory'],[],false,'/tmp/core-only.json'));
 eq(str_contains($coreOnly,'mybb-toolchain:'),false);eq(str_contains($coreOnly,'installed.json'),false);eq(str_contains($coreOnly,'none (core-only installation)'),true);
});
test('CLI resolves an explicit MyBB config path without executing the config file',function()use($tmp){
 $root=$tmp.'/cli-config-site';$sentinel=$tmp.'/config-was-executed';mkdir($root.'/inc',0755,true);file_put_contents($root.'/inc/class_core.php','$version = "1.8.41";');file_put_contents($root.'/global.php','<?php');file_put_contents($root.'/inc/config.php','<?php file_put_contents('.var_export($sentinel,true).', "executed");');
 $entry=dirname(__DIR__).'/mybb-cli/bin/mybb';$run=static function(array $command):array{$pipes=[];$process=proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new RuntimeException('Could not start CLI config-path check');fclose($pipes[0]);$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);return [proc_close($process),$stdout,$stderr];};
 [$code,$stdout,$stderr]=$run([PHP_BINARY,$entry,'core','status','--config='.$root.'/inc/config.php','--format=json']);eq($code,0);eq($stderr,'');$status=json_decode($stdout,true,512,JSON_THROW_ON_ERROR);eq($status['site_root'],realpath($root));eq($status['mybb_version'],'1.8.41');eq(is_file($sentinel),false);
 [$code,$stdout,$stderr]=$run([PHP_BINARY,$entry,'core','status','--config='.$root.'/inc/config.php','--format=table']);eq($code,0);eq($stderr,'');if(!str_starts_with($stdout,'+')||!str_contains($stdout,'| Field ')||!str_contains($stdout,'| status '))throw new RuntimeException('CLI --format=table did not render a structured table.');
 [$code,$stdout,$stderr]=$run([PHP_BINARY,$entry,'core','status','--path='.$root,'--config='.$root.'/inc/config.php','--json']);eq($code,2);$error=json_decode($stdout,true,512,JSON_THROW_ON_ERROR);eq($error['error']['code'],'usage');eq(is_file($sentinel),false);
});
test('CLI table output is column-aligned and strips terminal controls from values',function(){
 $table=MyBB\Tooling\TextTable::render(['status'=>'ok','path'=>"/tmp/forum\x1b[31m|root",'nested'=>['count'=>2]]);
 if(!str_starts_with($table,"+--------+"))throw new RuntimeException('CLI table output does not use a column grid.');
 eq(str_contains($table,"\x1b"),false);eq(str_contains($table,'\\|root'),true);eq(str_contains($table,'{"count":2}'),true);eq(substr_count($table,'|'),13);
});
